INSERT INTO `scenario_templates` (`id`, `asset_config`, `created_at`, `created_by`, `deployment_order`, `description`, `difficulty_level`, `estimated_duration`, `evaluation_criteria`, `exercise_script`, `instructor_notes`, `is_active`, `is_public`, `last_used_at`, `learning_objectives`, `max_participants`, `name`, `network_topology`, `prerequisites`, `scenario_type`, `student_guidelines`, `success_metrics`, `tags`, `updated_at`, `usage_count`) VALUES (1, '{\n  \"assets\": [\n    {\"type\": \"web_server\", \"name\": \"目标Web服务器\", \"vulnerabilities\": [\"sql_injection\", \"xss\", \"file_upload\"]}\n  ],\n  \"objectives\": [\n    \"获取管理员权限\",\n    \"提取敏感数据\",\n    \"建立持久化后门\"\n  ],\n  \"tools\": [\"sqlmap\", \"burpsuite\", \"metasploit\"],\n  \"timeLimit\": 120\n}', '2025-08-12 21:50:08.017217', 1, NULL, '针对Web应用的综合渗透测试场景，包括SQL注入、XSS、文件上传等常见漏洞利用', 'intermediate', NULL, NULL, NULL, NULL, b'1', b'1', NULL, NULL, NULL, 'Web应用渗透测试', NULL, NULL, 'red_team', NULL, NULL, NULL, '2025-08-12 21:50:08.017225', 0);
INSERT INTO `scenario_templates` (`id`, `asset_config`, `created_at`, `created_by`, `deployment_order`, `description`, `difficulty_level`, `estimated_duration`, `evaluation_criteria`, `exercise_script`, `instructor_notes`, `is_active`, `is_public`, `last_used_at`, `learning_objectives`, `max_participants`, `name`, `network_topology`, `prerequisites`, `scenario_type`, `student_guidelines`, `success_metrics`, `tags`, `updated_at`, `usage_count`) VALUES (2, '{\n  \"assets\": [\n    {\"type\": \"domain_controller\", \"name\": \"域控制器\"},\n    {\"type\": \"file_server\", \"name\": \"文件服务器\"},\n    {\"type\": \"workstation\", \"name\": \"办公终端\"}\n  ],\n  \"attack_scenarios\": [\n    \"钓鱼邮件投递\",\n    \"权限提升\",\n    \"横向移动\",\n    \"数据窃取\"\n  ],\n  \"defense_tools\": [\"SIEM\", \"EDR\", \"IDS/IPS\", \"威胁情报平台\"],\n  \"success_criteria\": [\"检测到初始入侵\", \"阻止权限提升\", \"隔离受感染主机\"]\n}', '2025-08-12 21:50:08.038143', 1, NULL, '模拟高级持续性威胁(APT)攻击，训练蓝队的检测、分析和响应能力', 'advanced', NULL, NULL, NULL, NULL, b'1', b'1', NULL, NULL, NULL, 'APT攻击检测与响应', NULL, NULL, 'blue_team', NULL, NULL, NULL, '2025-08-12 21:50:08.038152', 0);
INSERT INTO `scenario_templates` (`id`, `asset_config`, `created_at`, `created_by`, `deployment_order`, `description`, `difficulty_level`, `estimated_duration`, `evaluation_criteria`, `exercise_script`, `instructor_notes`, `is_active`, `is_public`, `last_used_at`, `learning_objectives`, `max_participants`, `name`, `network_topology`, `prerequisites`, `scenario_type`, `student_guidelines`, `success_metrics`, `tags`, `updated_at`, `usage_count`) VALUES (3, '{\n  \"network_topology\": {\n    \"dmz\": [\"web_server\", \"mail_server\", \"dns_server\"],\n    \"internal\": [\"domain_controller\", \"database_server\", \"file_server\"],\n    \"workstations\": [\"hr_pc\", \"finance_pc\", \"admin_pc\"]\n  },\n  \"red_team_objectives\": [\n    \"获取域管理权限\",\n    \"窃取财务数据\",\n    \"破坏业务连续性\"\n  ],\n  \"blue_team_objectives\": [\n    \"检测并阻止攻击\",\n    \"保护核心资产\",\n    \"快速事件响应\"\n  ],\n  \"duration\": 480\n}', '2025-08-12 21:50:08.040855', 1, NULL, '大型企业网络环境下的红蓝对抗演练，涵盖多个攻击向量和防御策略', 'advanced', NULL, NULL, NULL, NULL, b'1', b'1', NULL, NULL, NULL, '企业网络综合攻防演练', NULL, NULL, 'mixed', NULL, NULL, NULL, '2025-08-12 21:50:08.040861', 0);
